var import_obsidian6 = require("obsidian");

// src/utils/render-scheduler.ts
var defaultSchedule = (callback) => {
  if (typeof queueMicrotask === "function") {
    queueMicrotask(callback);
    return;
  }
  setTimeout(callback, 0);
};
function createRenderScheduler(render, schedule = defaultSchedule) {
  let scheduled = false;
  let running = false;
  let queuedWhileRunning = false;
  let generation = 0;
  const run = () => {
    running = true;
    try {
      render();
    } finally {
      running = false;
      if (queuedWhileRunning) {
        queuedWhileRunning = false;
        run();
      }
    }
  };
  return {
    request() {
      if (running) {
        queuedWhileRunning = true;
        return;
      }
      if (scheduled)
        return;
      scheduled = true;
      const myGeneration = generation;
      schedule(() => {
        if (myGeneration !== generation)
          return;
        scheduled = false;
        run();
      });
    },
    cancel() {
      generation++;
      scheduled = false;
      queuedWhileRunning = false;
    },
    isScheduled() {
      return scheduled || queuedWhileRunning;
    }
  };
}

