    const activePath = this.app.workspace?.getActiveFile?.()?.path;
    const explicitContexts = this.contextManager.getContexts().filter((ctx) => !(ctx.type === "scope" && ctx.scope === "current")).filter((ctx) => !(ctx.type === "file" && ctx.data === activePath));
