  async handlePaste(e) {
    const clipboard = e.clipboardData;
    if (!clipboard)
      return;
    const items = clipboard.items;
    if (items) {
      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        if (item.type.indexOf("image") === -1)
          continue;
        if (!this.modelService.getProviderCapabilities().supportsImageInput) {
          new import_obsidian20.Notice("The active provider does not support image context.");
          return;
        }
        e.preventDefault();
        const blob = item.getAsFile();
        if (blob) {
          const reader = new FileReader();
          reader.onload = (event) => {
            const base64 = event.target?.result;
            this.contextManager.addContext({
              id: Date.now().toString(),
              type: "image",
              data: base64,
              summary: "Pasted Image"
            });
            this.renderContextChips(this.outputContainer.parentElement?.querySelector(".shell-context-chips"));
          };
          reader.readAsDataURL(blob);
        }
        return;
      }
    }
    const text = clipboard.getData("text/plain").trim();
    if (text && this.isValidUrl(text)) {
      e.preventDefault();
      const type = text.includes("youtube.com") || text.includes("youtu.be") ? "youtube" : "url";
      this.contextManager.addContext({
        id: Date.now().toString(),
        type,
        data: text,
        summary: text
      });
      this.renderContextChips(this.outputContainer.parentElement?.querySelector(".shell-context-chips"));
    }
  }
  handleDrop(e) {
    e.preventDefault();
    if (!this.modelService.getProviderCapabilities().supportsImageInput) {
      new import_obsidian20.Notice("The active provider does not support image context.");
      return;
    }
    if (e.dataTransfer?.files) {
      for (let i = 0; i < e.dataTransfer.files.length; i++) {
        const file = e.dataTransfer.files[i];
        if (file.type.startsWith("image/")) {
          const reader = new FileReader();
          reader.onload = (event) => {
            const base64 = event.target?.result;
            this.contextManager.addContext({
              id: Date.now().toString(),
              type: "image",
              data: base64,
              summary: file.name
            });
            this.renderContextChips(this.outputContainer.parentElement?.querySelector(".shell-context-chips"));
          };
          reader.readAsDataURL(file);
        }
      }
    }
  }
